package com.bct.ngtpa.apiservice.adapter.in.web.auth.login.mapper;import com.bct.ngtpa.apiservice.adapter.in.web.auth.login.dto.*;import com.bct.ngtpa.apiservice.adapter.in.web.auth.login.dto.LoginWorkflowResultResponse;import com.bct.ngtpa.apiservice.adapter.in.web.response.*;import com.bct.ngtpa.apiservice.application.dto.workflow.*;import com.bct.ngtpa.apiservice.application.usecase.auth.login.otp.verify.*;import java.util.*;public final class LoginOtpVerifyWebMapper {public MutationResponse<LoginWorkflowResultResponse<LoginOtpVerifyDataResponse>> toMutationResponse(VerifyLoginOtpResult r){if(r.status()==VerifyLoginOtpStatus.ACCOUNTS_READY)return MutationResponse.success(ApiStatus.SUCCESS,payload(WorkflowNextStep.SELECT_ACCOUNT,r,List.of()),List.of());WorkflowNextStep next=r.status()==VerifyLoginOtpStatus.VERIFY_ATTEMPTS_EXCEEDED?WorkflowNextStep.RESTART_FLOW:WorkflowNextStep.VERIFY_OTP;String code=switch(r.status()){case INVALID->LoginErrorKey.OTP_INVALID.value();case EXPIRED->LoginErrorKey.OTP_EXPIRED.value();case VERIFY_ATTEMPTS_EXCEEDED->LoginErrorKey.OTP_VERIFY_ATTEMPTS_EXCEEDED.value();case AUTH_FLOW_INVALID->LoginErrorKey.AUTH_FLOW_INVALID.value();case ACCOUNT_LIST_UNAVAILABLE->LoginErrorKey.ACCOUNT_LIST_UNAVAILABLE.value();case ZERO_VALID_ACCOUNTS->LoginErrorKey.NO_ACCESSIBLE_ACCOUNTS.value();default->SharedWorkflowErrorKey.SYSTEM_UNAVAILABLE.value();};var actions=r.status()==VerifyLoginOtpStatus.VERIFY_ATTEMPTS_EXCEEDED?List.of(new LoginOtpActionResponse(WorkflowNextStep.RESTART_FLOW.toString())):List.<LoginOtpActionResponse>of();ApiStatus status=r.status()==VerifyLoginOtpStatus.SYSTEM_FAILED?ApiStatus.SYSTEM_ERROR:r.status()==VerifyLoginOtpStatus.ACCOUNT_LIST_UNAVAILABLE?ApiStatus.DOWNSTREAM_ERROR:ApiStatus.BUSINESS_REJECTED;return MutationResponse.failure(status,payload(next,r,actions),List.of(ApiError.form(code,null,List.of(r.status()==VerifyLoginOtpStatus.INVALID?"otpCode":"PAGE"),"BFF")));}public MutationResponse<LoginWorkflowResultResponse<LoginOtpVerifyDataResponse>> missing(String code,String target){return MutationResponse.failure(ApiStatus.VALIDATION_FAILED,payload(WorkflowNextStep.VERIFY_OTP,null,List.of()),List.of(ApiError.form(code,null,List.of(target),"BFF")));}private LoginWorkflowResultResponse<LoginOtpVerifyDataResponse> payload(WorkflowNextStep step,VerifyLoginOtpResult r,List<LoginOtpActionResponse> actions){var accounts=r==null?List.<LoginOtpAccountResponse>of():r.accounts().stream().map(a->new LoginOtpAccountResponse(a.accountRef().value())).toList();return new LoginWorkflowResultResponse<>(step,new LoginOtpVerifyDataResponse(r==null?null:r.remainingVerifyAttempts(),actions,accounts));}}
